from collections import defaultdict

def stats_par_ville(ventes):
    groupes = defaultdict(list)
    for ville, montant in ventes:
        groupes[ville].append(montant)
    resultat = {}
    for ville, montants in groupes.items():
        resultat[ville] = {
            "total": round(sum(montants), 2),
            "nombre": len(montants),
            "moyenne": round(sum(montants) / len(montants), 2),
        }
    return resultat

