import math

def _ecart_type_exact(valeurs):
    m = sum(valeurs) / len(valeurs)
    return math.sqrt(sum((x - m) ** 2 for x in valeurs) / len(valeurs))

def ecart_type(valeurs):
    return round(_ecart_type_exact(valeurs), 3)

def standardiser(valeurs):
    m = sum(valeurs) / len(valeurs)
    et = _ecart_type_exact(valeurs)
    if et == 0:
        return [0.0] * len(valeurs)
    return [round((x - m) / et, 2) for x in valeurs]

