import csv
import io

def rapport(texte_csv):
    par_ville = {}
    ignorees = 0
    for l in csv.DictReader(io.StringIO(texte_csv)):
        try:
            montant = float(l["montant"])
        except ValueError:
            ignorees += 1
            continue
        par_ville[l["ville"]] = par_ville.get(l["ville"], 0) + montant
    meilleure = max(par_ville, key=par_ville.get) if par_ville else None
    return {"total": round(sum(par_ville.values()), 2), "meilleure_ville": meilleure, "lignes_ignorees": ignorees}
